  let q = (2 * b^3 - 9 * a * b * c + 27 * a^2 * d) / (27 * a^3);
  let disc = (q / 2)^2 + (p / 3)^3;
  let sqrtDisc = sqrt(disc);
  let u = -(q / 2) + sqrtDisc;
  let v = -(q / 2) - sqrtDisc;
